import numpy as np

class landscape:

    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Spherical component (ensures global minimum at origin)
        spherical = np.sum(x**2)
        # Harmonic component (adds local minima with controlled basin sizes)
        harmonic = np.sum(np.abs(x))
        # Combined function with balanced contributions
        return spherical + 0.1 * harmonic * np.sqrt(spherical + 1e-10)
